from pyquest import *


def draw_pipe(x, gap_y):
    draw_image("images/pipe.png", x, gap_y - 440, flip=True)
    draw_image("images/pipe.png", x, gap_y + GAP)


GAP = 150
pipes = [450, 650]


def update():
    for i in range(len(pipes)):
        pipes[i] = pipes[i] - 2
        if pipes[i] < -76:
            pipes[i] = pipes[i] + 400


def draw():
    clear("skyblue")
    for x in pipes:
        draw_pipe(x, 200)
